void Solver::bump_var(int var, double coeff) {
    double new_act = activity[var] + var_inc * coeff;
    activity[var] = new_act;
    if (new_act > 1e100) {
        // Rescale all activities to prevent floating point overflow
        double scale = 1e-100;
        for (int i = 1; i <= vars; i++) activity[i] *= scale;
        var_inc *= scale;
        activity[var] = new_act * scale;
    }
    // Apply an extra small bump based on current decision level proximity
    // to give a slight preference to recently active variables
    if (level[var] > 0) {
        activity[var] += var_inc * coeff * 0.1;
        if (activity[var] > 1e100) {
            double scale = 1e-100;
            for (int i = 1; i <= vars; i++) activity[i] *= scale;
            var_inc *= scale;
        }
    }
    if (vsids.inHeap(var)) vsids.update(var);   // update heap position
}
// end

